  "航空区画を選んで出口を設定。航空隊の機種と機数は下の欄で編集できます": "Select an aviation compartment to configure exits. Edit craft type and count below",
  "船体をタップしてカッターを置く。寸法と位置を調整してから切り取る": "Tap the hull to place a cutter. Adjust its size and position, then cut",
  "外殻装甲の質量は表面積に比例します。削って凹凸を増やすほど同じ厚さでも重くなります。集中防御はジェネレーター・シールド発生器・ハイパードライブの表面だけを囲み、露出した反応炉の弱点を補います。": "Outer hull armor mass scales with surface area: more carved detail makes the same armor thickness heavier. Concentrated protection surrounds only reactors, shield generators, and hyperdrives, protecting exposed reactors.",
  "艦種と寸法": "Ship Class and Dimensions",
  "この端末のブラウザに保存": "Saved in this device's browser",
  "2 · 船体の型": "2 · Hull Shape",
  "全長は艦種の範囲で1 m単位。全幅・全高は船体の型の比率から始まり、個別に調整できます。設計中も「船体」タブで変更できます。": "Length adjusts in 1 m steps within the ship class range. Beam and height start from the hull shape's proportions and can be adjusted separately. You can change these in the Hull tab while designing.",
  "この船体で設計を始める": "Start Designing This Hull",
  "超兵器": "Superweapons",
  "シールドの目標強度": "Target Shield Strength",
  "目標強度 × 外表面積で必要電力が決まります。発生器の容量と給電が不足すると実効強度が下がります。": "Required power equals target strength multiplied by external surface area. Insufficient generator capacity or power reduces actual strength.",
  "標準に対して": "Relative to Standard",
  "炉とノズルで機関を組む": "Connect Reactors and Nozzles",
  "接続された機関は自動生成され、航空区画の自動充填から除外されます。": "Connected machinery is generated automatically and excluded from automatic hangar filling.",
  "内部を透視する": "View Interior in X-ray",
  "動力の接続": "Power Connections",
  "区画の能力": "Compartment Capabilities",
  "船体の組立": "Hull Assembly",
  "船体断面・艦尾を設計": "Design Hull Sections and Stern",
  "甲板・舷側帯・艦尾位置": "Deck, Side Belt, and Stern Position",
  "所属陣営": "Faction",
  "内部区画は外殻内に収容。箱形区画の干渉は必要容積を保って自動統合します。主炉・シールド・エンジンと外装機器は張出し可能。": "Internal compartments stay inside the outer hull. Overlapping box compartments merge automatically while preserving volume. Reactors, shields, engines, and exterior equipment may project outside.",
  "主砲ごとの充電装置": "Charging Equipment per Main Gun",
  "炉の大きさと発電出力": "Reactor Size and Power Output",
  "艦の性能": "Ship Performance",
  "射程別の毎秒火力（主射界）": "Damage per Second by Range (Main Arc)",
  "面ごとの装甲": "Armor by Surface",
  "シールドを抜けた砲火は面と区画ごとの装甲に負荷として溜まり、厚さに応じた限界を超えると貫通して奥のモジュールに当たる。負荷は時間とともに抜ける。": "Fire passing the shields adds stress to each surface and compartment's armor. Once stress exceeds the thickness-dependent limit, shots penetrate and strike modules behind it. Stress dissipates over time.",
  "径・全長を変更 / 機関胴を外に露出": "Adjust Diameter / Length; Expose Engine Body",
  "ノズル径を変更 / タービンを船内へ": "Adjust Nozzle Diameter; Keep Turbine Inside",
  "艦橋本体はそれだけで指揮所として働きます（どちらも前面の円筒ポッドから視界を測ります）。役割は選択後に変更でき、支持塔は構造パーツで組み立てます。配置後に位置・寸法・向きを調整できます。": "Bridge bodies provide command by themselves, measuring visibility from their forward cylindrical pods. Change the role after selection and build support towers from structural parts. Position, size, and orientation remain adjustable after placement.",
  "座標を指定して配置": "Place by Coordinates",
  "構造パーツから艦橋を組む": "Build a Bridge from Structural Parts",
  "格納容量（航空機・搭載艦・車両で共用）": "Shared Hangar Capacity: Craft, Ships, and Vehicles",
  "サイズ": "Size Units",
  "搭載を追加": "Add Complement",
  "格納区画の容積": "Hangar Volume",
  "設計で決めるのは格納区画の大きさと出入口だけです。航空機・搭載艦・地上部隊の車両を積むのは「編成」画面です（": "The designer sets hangar size and entrances. Add craft, ships, and ground vehicles in Fleet Organization (",
  "お任せ": "Automatic",
  "兵員と車両の容積": "Troop and Vehicle Volume",
  "設計で決めるのは乗せられる量だけです。陸戦隊（歩兵・ドロイド・車両）を乗せるのは「編成」画面です（": "The designer sets capacity only. Add infantry, droids, and vehicles in Fleet Organization (",
  "車両（格納庫と共用）": "Vehicles (Shared Hangar Space)",
  "着陸": "Landing",
  "空き容積と乗員を確認": "Review Free Volume and Crew",
  "できない": "Unavailable",
  "艦橋に付随する指揮区画": "Command Compartments Associated with Bridges",
  "コルサント低軌道": "Low Coruscant Orbit",
  "設計した艦を軌道上で操艦し、速力・加速・旋回と砲塔の射界を確かめます。": "Pilot your design in orbit to check speed, acceleration, turning, and turret firing arcs.",
  "公試に出る": "Start a Trial",
  "加速度が 0 G のため航行できません。推進・慣性補償・構造の上限を確認してください。": "Cannot fly with 0 G acceleration. Check propulsion, inertial compensation, and structural limits.",
  "3D視点の準備中…（この星系の艦の3Dモデル）": "Preparing 3D view… (ship models for this system)",
  "戦域": "Theater",
  "旗": "Flag",
  "艦を追加": "Add Ship",
  "構造": "Structure",
  "配置の向き": "Placement Orientation",
  "空き容積と乗員": "Free Volume and Crew",
  "円柱": "Cylinder",
  "球・楕円体": "Sphere / Ellipsoid",
  "半透明の立体を船体に重ね、重なった部分を切り取ります。位置と大きさを決めてから実行できます。": "Overlap the hull with a translucent solid to cut away the intersecting volume. Set its position and size before applying.",
  "1 · 大きさを決める": "1 · Set Size",
  "2 · 船体に重ねる": "2 · Overlap the Hull",
