  "後方": "Aft",
  "上方": "Above",
  "下方": "Below",
  "非武装": "Unarmed",
  "ジェネレーターがありません。出力ゼロでは何も動きません。": "No generator. Nothing operates without power.",
  "エンジンがありません。": "No engines installed.",
  "艦橋がありません。命中率が大きく落ちます。": "No bridge. Accuracy is greatly reduced.",
  "シールド発生器がありません。": "No shield generators installed.",
  "ハイパードライブがありません（星系内専用艦）。": "No hyperdrive: restricted to travel within a system.",
  "全陣営": "All Factions",
  "防御・船体維持": "Defense & Hull Support",
  "航空・輸送": "Aviation & Transport",
  "炉との間を機関として自動占有。接続炉・向き・口径を調整できます。": "Automatically reserves machinery space between nozzle and reactor. Adjust the reactor connection, direction, and diameter.",
  "主反応炉と同じ容積あたりの出力を持つ補助炉。独立したノズルの接続先にもできます。": "Auxiliary reactor with the same power density as the main reactor. It can also power independently connected nozzles.",
  "反応物を貯蔵。搭載量と出力から巡航時の持続時間を算出します。": "Stores reactants. Cruise endurance is calculated from stored fuel and reactor output.",
  "ポンプ・弁・供給設備。搭載量に応じて燃料供給能力を確保します。": "Pumps, valves, and feed systems. Fuel delivery capacity depends on installed equipment volume.",
  "電力の蓄積設備。武装への配電の起点で、近くの砲ほど配電路が短く済みます（出せる電力は蓄電量を30秒で出し切る分まで、残りは炉から直接）。戦闘ではシールドへの給電を肩代わりし、炉の出力を推進や兵装に回している間もシールドを再生させます。満充電のシールドの余剰給電で充電され、イオン砲の被弾で奪われます。": "Energy storage and a distribution point for nearby weapons, reducing conduit length. Maximum output empties the stored energy in 30 seconds; additional power comes directly from reactors. In combat it can power shield regeneration while reactor output supports engines or guns. Surplus power to fully charged shields recharges the cells; ion hits drain them.",
  "慣性制御装置の対応質量が不足しています。": "Inertial compensation capacity is insufficient for the ship's mass.",
  "構造維持装置の対応質量が不足しています。": "Structural integrity field capacity is insufficient for the ship's mass.",
