  "ジャンプにはリアクターの全出力が要ります。発進準備中は砲撃できず、被弾している間は準備が止まります。": "A jump requires full reactor output. Guns cannot fire during preparation, and incoming hits halt preparation.",
  "航行不能艦のある任務群はジャンプできません（回収か自沈を）": "Task forces with disabled ships cannot jump: recover or scuttle them",
