  "第": "No.",
  "星系間航空攻撃（ハイパードライブ搭載機の飛行隊）": "Inter-system Air Raid (Hyperdrive-equipped Wings)",
  "ハイパードライブを持つ機体（Xウイング・Yウイング・Aウイング・Bウイング・Uウイング・ARC-170 など）だけの飛行隊は、母艦の星系から {2} 光年以内の星系を攻撃できます。到着後はいちばん近い主力艦を攻撃し、兵装を使い切ると母艦のいる星系へ戻ります。": "Wings composed entirely of hyperdrive-equipped craft, such as X-, Y-, A-, B-, U-wings or ARC-170s, can raid systems within {2} light-years of their carrier. On arrival they attack the nearest capital ship, then return to the carrier's system when their ammunition is spent.",
  "· 発進まで": "· Time to Launch",
  "帰還命令済み": "Recall Ordered",
  "{1}から · {2}": "From {1} · {2}",
  "攻撃に出す": "Launch Attack",
  "到着まで {0} · {1} 光年": "Arrival in {0} · {1} ly",
  "{1}と合流": "Join {1}",
  "照準部位": "Target Subsystem",
  "斉射：同じ種類の砲がそろって撃ちます。一度に当たるので装甲を破りやすく（大口径の砲ほど効きます）、最初の斉射は目標が射程に入った瞬間に撃てます。待つぶん発射数はわずかに減り、斉射の合間は敵が射撃を受けません（敵のハイパードライブ充填が進みます）。": "Salvo: guns of the same type fire together, improving armor penetration, especially with large calibers. The first salvo can fire as soon as a target enters range. Waiting slightly reduces total shots and leaves gaps in incoming fire, allowing an enemy hyperdrive to charge.",
  "連続射撃：各砲が装填しだい撃ち続けます。発射数がいちばん多く、敵を絶えず射撃下に置いてハイパードライブの充填を止めます。": "Continuous Fire: each gun fires as soon as it reloads, maximizing shots and maintaining pressure to interrupt enemy hyperdrive charging.",
  "艦によって射撃の型が違います。": "Ships have different firing patterns.",
  "自動：ふだんは艦全体を撃ちます。自艦の2.5倍以上の大きさの艦はシールドが弱まると艦橋を狙います。": "Auto: normally targets the whole ship. Against ships at least 2.5 times larger, it targets the bridge once shields weaken.",
  "艦橋・砲塔は装甲の外にあります。シールドが弱まると、狙いを保てた分（近いほど・的が大きいほど多い）が装甲を通さず直撃します。": "Bridges and turrets sit outside the armor. When shields weaken, sufficiently accurate shots hit them directly, bypassing armor; closer and larger targets are easier to hit.",
  "狙った部位のある区画に被弾が集まります。": "Hits concentrate on compartments containing the selected subsystem.",
  "充電中": "Charging",
  "過負荷・冷却中": "Overloaded / Cooling",
  "使用不能": "Unavailable",
  "· 超兵器 照射中": "· Superweapon Firing",
  "· 超兵器 発射可": "· Superweapon Ready",
  "· 超兵器 充電 {0}%": "· Superweapon Charging {0}%",
  "· 超兵器 過負荷": "· Superweapon Overload",
  "過負荷・冷却 {0} 秒": "Overload Cooldown {0} s",
  "自由発射": "Fire at Will",
  "発射待機": "Hold Fire",
  "自由発射：充電が済んで射界に敵が入ると自動で撃ちます（超重合成ビームは艦首、ハイパーイオン砲は舷側の固定射界）。撃つと給電している炉が過負荷になり、しばらく出力が落ちます。発射待機：充電したまま撃たずに待ちます。": "Fire at Will automatically fires when charged and an enemy enters the fixed arc: forward for the composite beam, broadside for the hyper-ion cannon. Firing overloads supplying reactors and temporarily reduces their output. Hold Fire retains the charge without firing.",
  "拿捕中（移乗 {0}%）": "Boarding {0}%",
  "拿捕のため接近中": "Approaching to Capture",
  "牽引中": "Towing",
  "牽引のため接近中": "Approaching to Tow",
  "トラクター・ビーム（{0} 隻が装備）": "Tractor Beams ({0} Equipped Ships)",
  "拿捕": "Capture",
  "牽引：戦闘不能の味方艦を捕まえて連れて行きます（ジャンプにも同行）。拿捕：シールドを失った戦闘不能の敵艦を捕まえ、陸戦隊が移乗して奪います。": "Tow disabled friendly ships, including through jumps. Capture disabled, unshielded enemy ships by holding them with tractor beams and boarding with ground troops.",
  "任務群への命令": "Task Force Orders",
  "{0} 隻が個別の命令で行動中": "{0} Ships Following Individual Orders",
  "任務群に戻す": "Return to Task Force",
  "離脱にはリアクターの全出力が要ります。準備中は砲撃できず、被弾している間は準備が止まります（距離を取りながら準備します）。": "Withdrawal requires full reactor output. Guns cannot fire during preparation, and hits halt progress. Ships prepare while opening distance.",
